INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(21701, 'Zephaniah 2:11', 'Zephaniah', 2, 11, '&nbsp;مالِک خُدائ به هغوئ ويروى کله چې هغه د ټولې دُنيا خُدايان کمزورى کړى. د دُنيا ټول قومونه به د هغۀ عبادت وکړى، او هر يو به يې په خپل مُلک کښې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21702, 'Zephaniah 2:12', 'Zephaniah', 2, 12, '&nbsp;”اے د ايتهوپيا خلقو، تاسو به هم زما په تُوره ووژلے شئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21703, 'Zephaniah 2:13', 'Zephaniah', 2, 13, '&nbsp;هغه به خپل لاس اوږد کړى د شمال خلاف او اسور به تباه کړى، نينوه به شاړ او ويجاړ کړى او لکه د صحرا په شان به يې اوچ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21704, 'Zephaniah 2:14', 'Zephaniah', 2, 14, '&nbsp;څاروى او رمې او هر قسمه مخلوق به هلته آرام کوى. ګونګى به د دې د ستنو په سر کښې جالې جوړې کړى. د دوئ چغې به د کړکو نه دننه راځى، ملبه به د دې په دُرشلونو کښې وى، خلق به د دې دِيار تيرونه وزغلوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21705, 'Zephaniah 2:15', 'Zephaniah', 2, 15, '&nbsp;دا هم هغه لاپرواه ښار دے چې په حفاظت کښې پروت وو. هغې خپل ځان سره ووئيل، ”زۀ د ټولو نه غټ يم، او زما نه علاوه بل نشته.“ هغې نه څۀ کنډر جوړ شو او د ځنګلى ځناورو جاله شوه. هر هغه څوک چې په هغې تېريږى نو ورپورې به مسخرې کوى او د يرې نه به توبې وباسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21706, 'Zephaniah 3:1', 'Zephaniah', 3, 1, '&nbsp;افسوس د ظالمانو په ښار چې سرکشه او ناپاکه دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21707, 'Zephaniah 3:2', 'Zephaniah', 3, 2, '&nbsp;هغه د هيچا تابعدارى نۀ کوى، هغه تربيت نۀ قبلوى. هغه په مالِک خُدائ يقين نۀ کوى، هغه خپل خُدائ پاک ته نزدې نۀ راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21708, 'Zephaniah 3:3', 'Zephaniah', 3, 3, '&nbsp;د دې آفسران غړمبېدونکى زمرى دى، د دې حکمرانان د ماښام ليوانو په شان دى، څوک چې تر سحر پورې خپل ټول ښکار خورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21709, 'Zephaniah 3:4', 'Zephaniah', 3, 4, '&nbsp;د دې پېغمبران کبرژن دى، هغوئ غداران دى، د هغې اِمامان د مقدسو ځايونو بې‌حرمتى کوى او د شريعت نافرمانى کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21710, 'Zephaniah 3:5', 'Zephaniah', 3, 5, '&nbsp;مالِک خُدائ په هغه ښار کښې دے هغه صادق دے، هغه هيڅ بې‌اِنصافى نۀ کوى. هغه هر سحر اِنصاف کوى او هره ورځ خپل اِنصاف قائم ساتى. خو بدعمله خلق هيڅ په شرم نۀ پوهيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21711, 'Zephaniah 3:6', 'Zephaniah', 3, 6, '&nbsp;”ما قومونه ختم کړل، د هغوئ قلعه ګانې مې تباه کړې، ما د هغوئ کوڅې ويجاړې کړې، په هغې کښې څوک تګ راتګ نۀ کوى. د هغوئ ښارونه خالى شوى دى، هيڅ څوک به په کښې پاتې نۀ شى، يو هم نه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21712, 'Zephaniah 3:7', 'Zephaniah', 3, 7, '&nbsp;ما ښار ته ووئيل، يقيناً به تۀ زما نه وويرېږې او زما تربيت به قبول کړې. بيا به د هغۀ د اوسېدو ځائ تباه نۀ شى، لکه څنګه چې زما د هغۀ خلاف منصوبه وه. خو د هغوئ اوس هم دا شوق دے چې هغه ټولې بدعملۍ چې کومې يې مخکښې کولې وکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21713, 'Zephaniah 3:8', 'Zephaniah', 3, 8, '&nbsp;مالِک خُدائ فرمائى چې، ”په دې وجه ما ته انتظار وکړئ، په کومه ورځ چې زۀ به ښکار ونيسم. ما فېصله کړې ده چې قومونه راغونډ کړم، بادشاهۍ رايوځائ کړم، او خپل قهر او سخته غصه پرې نازله کړم. زما د غېرتى قهر په اور به ټوله دُنيا وسوزى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21714, 'Zephaniah 3:9', 'Zephaniah', 3, 9, '&nbsp;بيا به زۀ د خلقو خبرې پاکې کړم، چې هغوئ ټول د مالِک خُدائ نوم واخلى او اوږه په اوږه د هغۀ خِدمت وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21715, 'Zephaniah 3:10', 'Zephaniah', 3, 10, '&nbsp;د ايتهوپيا د سيندونو بل طرف نه به زما عبادت کوونکى، زما خوارۀ وارۀ خلق، ما له نذرانې راوړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21716, 'Zephaniah 3:11', 'Zephaniah', 3, 11, '&nbsp;په هغه ورځ به تاسو د هغه ټولو خراب کارونو په وجه چې تاسو ما سره کړى دى ونۀ شرمېږئ، ځکه چې زۀ به د دې ښار نه هغه خلق لرې کړم چې په خپل غرور خوشحالۍ کوى. تۀ به بيا کله زما په مقدس غر غرور ونۀ کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21717, 'Zephaniah 3:12', 'Zephaniah', 3, 12, '&nbsp;خو زۀ به په تا کښې خاکساره او عاجز خويه خلق پرېږدم، څوک چې د مالِک خُدائ په نوم يقين کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21718, 'Zephaniah 3:13', 'Zephaniah', 3, 13, '&nbsp;د بنى اِسرائيلو ژوندى پاتې خلق به غلط کار نۀ کوى، هغوئ به دروغ نۀ وائى، او نۀ به د هغوئ په ژبه دوکه وى. هغوئ به خورى څښى او آرام به کوى او هيڅ څوک به هغوئ نۀ يروى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21719, 'Zephaniah 3:14', 'Zephaniah', 3, 14, '&nbsp;سندرې ووايه، اے د صيون لورې، په زوره چغې ووهه، اے بنى اِسرائيله. خوشحاله شه او په خپل پوره زړۀ سره خوشحالى وکړه، اے صيون لورې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21720, 'Zephaniah 3:15', 'Zephaniah', 3, 15, '&nbsp;مالِک خُدائ ستاسو سزا ختمه کړې ده، هغۀ ستاسو دشمنان واپس کړل. مالِک خُدائ، د اِسرائيل بادشاه، ستاسو مل دے، تاسو به بيا هيڅکله د څۀ نقصان نه نۀ يرېږئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21721, 'Zephaniah 3:16', 'Zephaniah', 3, 16, '&nbsp;په هغه ورځ به هغوئ يروشلم ته ووائى چې، ”يرېږه مه، اے صيونه، پرى نۀ ږدئ چې ستا لاسونه کمزورى پاتې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21722, 'Zephaniah 3:17', 'Zephaniah', 3, 17, '&nbsp;مالِک خُدائ ستاسو خُدائ پاک ستاسو مل دے، هغه طاقتور دے او تاسو به بچ کړى. هغه به تاسو نه ډېر خوشحاله وى، هغه به تا په خپلې مينې خاموش کړى، هغه به په تا په سندرو سره خوشحالى وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21723, 'Zephaniah 3:18', 'Zephaniah', 3, 18, '&nbsp;زۀ به هغوئ ستاسو نه لرې کړم څوک چې د مقرر شوى اخترونو په وجه غمژن وُو نو دا به نور ستاسو دپاره د شرم سبب نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21724, 'Zephaniah 3:19', 'Zephaniah', 3, 19, '&nbsp;په هغه وخت به زۀ معامله وکړم هغوئ ټولو سره چې په تا يې ظلم زياتے کړے دے، زۀ به ګوډيان بچ کړم او هغوئ به راغونډ کړم چې څوک خوارۀ وارۀ شوى دى. زۀ به هغوئ له عزت او جلال ورکړم، په هر مُلک کښې چرته چې دوئ رسوا شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21725, 'Zephaniah 3:20', 'Zephaniah', 3, 20, '&nbsp;په هغه وخت به زۀ تاسو راغونډ کړم، په هغه وخت به زۀ تاسو خپلو کورونو ته راولم. زۀ به تاسو ته د دُنيا په ټولو خلقو کښې عزت او جلال درکړم، زۀ به تاسو ستاسو د خپلو سترګو د وړاندې بيا آباد کړم،“ مالِک خُدائ فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21726, 'Haggai 1:1', 'Haggai', 1, 1, '&nbsp;د داريوس بادشاه د بادشاهۍ په دوېم کال د شپږمې مياشتې په اوله ورځ، د مالِک خُدائ کلام د حجى پېغمبر په وسيله زرُبابل د شلتى‌اېل په زوئ نازل شو چې د يهوداه حکمران وو، او يشوَع ته چې د مشر اِمام يهوصدق زوئ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21727, 'Haggai 1:2', 'Haggai', 1, 2, '&nbsp;”دا هغه څۀ دى چې مالِک خُدائ ربُ الافواج يې فرمائى، دا خلق وائى چې د مالِک خُدائ د کور بيا جوړولو وخت لا نۀ دے راغلے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21728, 'Haggai 1:3', 'Haggai', 1, 3, '&nbsp;بيا د مالِک خُدائ پېغام د حجى پېغمبر په ذريعه راغلو چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21729, 'Haggai 1:4', 'Haggai', 1, 4, '&nbsp;”آيا تاسو ته دا ښۀ ښکارى چې زما کور کنډر پروت وى او تاسو په عالى شان کورونو کښې اوسېږئ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21730, 'Haggai 1:5', 'Haggai', 1, 5, '&nbsp;اوس مالِک خُدائ ربُ الافواج فرمائى، تاسو سره چې څۀ کيږى ورباندې غور وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21731, 'Haggai 1:6', 'Haggai', 1, 6, '&nbsp;تاسو ډېر تخم کَرلے دے، خو فصل مو لږ رېبلے دے. تاسو خوراک کوئ خو ورباندې مړېږئ نه. تاسو اوبۀ څښئ، خو تنده مو پرې نۀ ختميږى. تاسو جامې اغوندئ، خو پرې نۀ ګرمېږئ. تاسو تنخواه ګټئ، خو صرف په هغه بټوه کښې اچولو دپاره چې په کښې سورى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21732, 'Haggai 1:7', 'Haggai', 1, 7, '&nbsp;مالِک خُدائ ربُ الافواج فرمائى چې په خپلو کارونو ډېر غور کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21733, 'Haggai 1:8', 'Haggai', 1, 8, '&nbsp;بره غر ته لاړ شئ او لرګى ترې لاندې راوړئ، او زما کور جوړ کړئ، نو چې زۀ پرې خوشحاله شم او عزتمند شم، مالِک خُدائ داسې فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21734, 'Haggai 1:9', 'Haggai', 1, 9, '&nbsp;تاسو د ډېرو په طمع وئ، خو وګورئ، دا لږ وختل. تاسو چې کور ته څۀ راوړل، هغه ما په هوا کښې والوځول. ولې؟ مالِک خُدائ ربُ الافواج فرمائى. زما د کور په وجه چې ګډ‌وډ پروت دے، او تاسو ټول په خپلو کورونو جوړولو کښې مصروف يئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21735, 'Haggai 1:10', 'Haggai', 1, 10, '&nbsp;نو ځکه ستاسو په وجه، آسمانونو پرخه ورول او زمکې فصل کول بند کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21736, 'Haggai 1:11', 'Haggai', 1, 11, '&nbsp;ما د اوچ کالۍ حکم کړے دے چې په زمکه او غرونو، په غله، په نوې ميو، په زيتُونو تېلو او په هر قسمه پېداوار چې زمکه يې کوى، په انسانانو او ځناورو، او ستاسو د لاسونو په محنت دې راشى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21737, 'Haggai 1:12', 'Haggai', 1, 12, '&nbsp;بيا زرُبابل د شلتى‌اېل زوئ، يشوَع د مشر اِمام يهوصدق زوئ، او د مالِک خُدائ پاتې شوو ټولو خلقو د مالِک خُدائ د هغوئ د خُدائ پاک خبرې ومنلې چې د حجى پېغمبر په ذريعه وئيلے شوې وې چې مالِک خُدائ د هغوئ خُدائ پاک هغه رالېږلے وو. او خلق د مالِک خُدائ نه ويرېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21738, 'Haggai 1:13', 'Haggai', 1, 13, '&nbsp;بيا حجى، د خُدائ پاک پېغمبر، خلقو ته د مالِک خُدائ دا پېغام ورسولو، ”زۀ ستاسو مل يم، مالِک خُدائ فرمائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21739, 'Haggai 1:14', 'Haggai', 1, 14, '&nbsp;نو مالِک خُدائ د زرُبابل د شلتى‌اېل د زوئ جذبه راپاروله چې د يهوداه حاکِم وو، او د يشوَع جذبه چې د مشر اِمام يهوصدق زوئ وو، او د مالِک خُدائ د ټولو ژوندى پاتې شوو خلقو جذبه. هغوئ راغلل او د مالِک خُدائ ربُ الافواج چې د هغوئ پاک خُدائ وو په کور يې کار شروع کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21740, 'Haggai 1:15', 'Haggai', 1, 15, '&nbsp;دا کار د داريوس بادشاه د بادشاهۍ په دوېم کال د شپږمې مياشتې په څليريشتمه ورځ شروع شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21741, 'Haggai 2:1', 'Haggai', 2, 1, '&nbsp;د اوومې مياشتې په يويشتمه ورځ، د مالِک خُدائ کلام په حجى پېغمبر نازل شو چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21742, 'Haggai 2:2', 'Haggai', 2, 2, '&nbsp;”زرُبابل د شلتى‌اېل زوئ ته چې د يهوداه حکمران دے، يشوَع ته چې د مشر اِمام يهوصدق زوئ دے، او د مالِک خُدائ پاتې شوى خلقو ته ووايه. هغوئ نه تپوس وکړئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21743, 'Haggai 2:3', 'Haggai', 2, 3, '&nbsp;په تاسو کښې داسې څوک پاتې دى چا چې د خُدائ د دې کور مخکښې شان او شوکت ليدلے وو؟ دا تاسو ته اوس څنګه ښکارى؟ ولې دا تاسو ته هيڅ هم نۀ ښکارى څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21744, 'Haggai 2:4', 'Haggai', 2, 4, '&nbsp;خو اوس تکړه شه، اے زرُبابله، مالِک خُدائ فرمائى چې، تکړه شه، اے يشوَع د مشر اِمام يهوصدق زويه، تکړه شه، اے د دې مُلک ټولو خلقو، مالِک خُدائ فرمائى، کار کوئ. ځکه چې زۀ ستاسو مل يم، مالِک خُدائ ربُ الافواج فرمائى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21745, 'Haggai 2:5', 'Haggai', 2, 5, '&nbsp;لکه څنګه چې ما تاسو سره وعده کړې وه کله چې تاسو د مِصر نه بهر راوتلئ. زما روح ستاسو په مينځ کښې دے نو تاسو مۀ يرېږئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21746, 'Haggai 2:6', 'Haggai', 2, 6, '&nbsp;مالِک خُدائ ربُ الافواج دا فرمائى چې، لږ وخت پس به زۀ آسمان او دُنيا، سمندر او اوچه زمکه وخوځوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21747, 'Haggai 2:7', 'Haggai', 2, 7, '&nbsp;زۀ به ټول قومونه ولړزوم، او د ټولو قومونو خزانې به راوړے شى او زۀ به دا کور د جلال نه ډک کړم، مالِک خُدائ ربُ الافواج فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21748, 'Haggai 2:8', 'Haggai', 2, 8, '&nbsp;سپين زر زما دى او سرۀ زر هم زما دى، مالِک خُدائ ربُ الافواج فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21749, 'Haggai 2:9', 'Haggai', 2, 9, '&nbsp;د دې موجوده کور جلال به د مخکښې کور د جلال نه زيات وى، مالِک خُدائ ربُ الافواج فرمائى. او زۀ به په دې ځائ کښې امن راولم. مالِک خُدائ ربُ الافواج فرمائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21750, 'Haggai 2:10', 'Haggai', 2, 10, '&nbsp;په څليريشتمه ورځ د نهمې مياشت، د داريوس د بادشاهۍ په دوېم کال، د مالِک خُدائ کلام په حجى پېغمبر نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21751, 'Haggai 2:11', 'Haggai', 2, 11, '&nbsp;”مالِک خُدائ ربُ الافواج وفرمائيل چې، اِمامانو نه تپوس وکړئ چې شريعت په دې حقله څۀ فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21752, 'Haggai 2:12', 'Haggai', 2, 12, '&nbsp;کۀ چرې يو سړے د قربانۍ نه مقدسه غوښه په خپله لمنه کښې واچوى او چرته يې وړى، او د هغۀ لمن روټۍ يا ترکارۍ، ميو، تېلو يا نور د خوراک څيزونو سره ولګى، آيا دا څيزونه به هم مقدس شى؟“ نو اِمامانو په جواب کښې ووئيل چې، ”نه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21753, 'Haggai 2:13', 'Haggai', 2, 13, '&nbsp;بيا حجى وفرمائيل، ”کۀ چرې يو سړے د مړى سره په لګېدو باندې ناپاک شى بيا کۀ هغه په دې کښې څۀ څيز سره ولګيږى، آيا دا به ناپاک شى؟“ ”آو،“ اِمامانو جواب ورکړو، ”دا به ناپاک شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21754, 'Haggai 2:14', 'Haggai', 2, 14, '&nbsp;بيا حجى وفرمائيل، ”زما په نظر کښې د دې خلقو او د دې قوم هم دا حال دے. مالِک خُدائ فرمائى چې، دوئ چې څۀ کوى او څۀ قربانى کوى هغه ناپاک دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21755, 'Haggai 2:15', 'Haggai', 2, 15, '&nbsp;د دې نه وړاندې چې د مالِک خُدائ د کور د بنياد کاڼى يو په بل نۀ وُو اېښودلے شوى، اوس دې خبرې ته ښۀ خيال وکړئ چې ستاسو به څۀ حال وو؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21756, 'Haggai 2:16', 'Haggai', 2, 16, '&nbsp;کله چې تاسو د غلې د شلو بورو په اُميد راغلى وئ، نو هلته صرف لس بورۍ وې. کۀ څوک د ميو چاټۍ ته راغلو چې سل ليټره ترې راوباسى، او هلته صرف پنځوس ليټره وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21757, 'Haggai 2:17', 'Haggai', 2, 17, '&nbsp;ما ستاسو د لاس په ټولو کارونو، تِليا او پپونکې او ږلۍ راوسته. خو تاسو بيا هم ما ته واپس رانۀ غلئ، مالِک خُدائ دا فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21758, 'Haggai 2:18', 'Haggai', 2, 18, '&nbsp;تاسو په دې نننۍ ورځ چې د نهمې مياشتې څليريشتم تاريخ دے سوچ وکړئ، کله چې په دې ورځ د مالِک خُدائ د کور بنياد کېښودلے شو. په دې فکر وکړئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21759, 'Haggai 2:19', 'Haggai', 2, 19, '&nbsp;زۀ اوس تاسو سره وعده کوم په دې وخت کښې چې غله لا په ګودام کښې شته، تاسو تر اوسه پورې خپل فصل نۀ دے لو کړے، او ستاسو د انګورو بوټو او د اينځرو ونو، انار او د زيتُونو ونو هيڅ مېوه لا نۀ ده کړې. خو د نن نه به زۀ تاسو له برکت درکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21760, 'Haggai 2:20', 'Haggai', 2, 20, '&nbsp;په هم هغه ورځ د هغې مياشتې په څليريشتمه ورځ د مالِک خُدائ کلام په دوېم ځل په حجى نازل شو چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21761, 'Haggai 2:21', 'Haggai', 2, 21, '&nbsp;”زرُبابل ته ووايه چې د يهوداه حکمران دے چې زۀ به آسمان او زمکه وخوځوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21762, 'Haggai 2:22', 'Haggai', 2, 22, '&nbsp;زۀ به شاهى تختونه اولټه کړم او د پردو حکومتونو طاقت به ختم کړم. زۀ به جنګى ګاډۍ او د دې چلوونکى په بل مخ واړوم، آسونه او د دې سوارۀ به يو بل ووژنى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21763, 'Haggai 2:23', 'Haggai', 2, 23, '&nbsp;مالِک خُدائ ربُ الافواج فرمائى چې، زۀ به تا په هغه ورځ بوځم، زما خِدمت کوونکى زرُبابل د شلتى‌اېل زويه، مالِک خُدائ فرمائى، او زۀ به تا لکه د خپل مهر د ګوتې په شان کړم، ځکه چې تۀ ما خوښ کړے يې. مالِک خُدائ ربُ الافواج دا فرمائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21764, 'Zechariah 1:1', 'Zechariah', 1, 1, '&nbsp;د فارس بادشاه داريوس د بادشاهۍ د دوېم کال په اتمه مياشت، د مالِک خُدائ کلام په زکرياه پېغمبر، د برکياه په زوئ چې د عدو زوئ وو نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21765, 'Zechariah 1:2', 'Zechariah', 1, 2, '&nbsp;”ستاسو پلار نيکۀ ته مالِک خُدائ ډېر غصه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21766, 'Zechariah 1:3', 'Zechariah', 1, 3, '&nbsp;نو په دې وجه خلقو ته ووايه چې، مالِک خُدائ ربُ الافواج فرمائى چې ما ته راواپس شئ، او زۀ به تاسو ته راواپس شم، مالِک خُدائ ربُ الافواج فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21767, 'Zechariah 1:4', 'Zechariah', 1, 4, '&nbsp;د خپل پلار نيکۀ په شان مۀ جوړېږئ، چا ته به چې پخوانو پېغمبرانو فرمائيل چې، ”مالِک خُدائ دا فرمائى چې، د خپلې بدعملۍ نه او د خپل بدعمله کارونو نه واوړئ.“ خو هغوئ به ما ته غوږ نۀ نيولو او نۀ به يې توجو راکوله، مالِک خُدائ ربُ الافواج فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21768, 'Zechariah 1:5', 'Zechariah', 1, 5, '&nbsp;خو ستاسو پلار نيکۀ اوس چرته دى؟ ولې هغوئ او پېغمبران به تر ابده ژوندى وى څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21769, 'Zechariah 1:6', 'Zechariah', 1, 6, '&nbsp;خو هر څۀ چې ما د خپلو خِدمتګارانو پېغمبرانو په وسيله ستاسو پلار نيکۀ ته وفرمائيل، هم هغه شان وشُو لکه څنګه چې ما حکم ورکړے وو. نو بيا هغوئ توبه وويسته او وې وئيل، مالِک خُدائ ربُ الافواج مونږ سره هغه څۀ وکړل د کوم چې زمونږ طريقې او عملونه حقدار وُو، هغۀ مونږ سره هغه څۀ وکړل د څۀ کولو چې هغۀ اراده کړې وه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21770, 'Zechariah 1:7', 'Zechariah', 1, 7, '&nbsp;د داريوس د بادشاهۍ په دوېم کال، د يوولسمې مياشتې په څليريشتمه ورځ چې د شيباط مياشت وه، د مالِک خُدائ کلام زکرياه د برکياه په زوئ چې د عدو زوئ وو نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21771, 'Zechariah 1:8', 'Zechariah', 1, 8, '&nbsp;په شپه کښې ما يوه رويا وليده، او هلته زما په وړاندې يو سړے په سُور آس سور وو. هغه آس د سر درو ونو په مينځ کښې په يو تنګه وادۍ کښې ولاړ وو. د هغۀ نه شاته سرۀ، نسوارى او سپين آسونه وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21772, 'Zechariah 1:9', 'Zechariah', 1, 9, '&nbsp;ما تپوس وکړو، ”دا څۀ دى، زما مالِکه؟“ هغه فرښتې چې ما سره يې خبرې کولې جواب راکړو، ”زۀ به تا ته وښايم چې دا څۀ دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21773, 'Zechariah 1:10', 'Zechariah', 1, 10, '&nbsp;بيا هغه سړے چې د سر درو ونو مينځ کښې ولاړ وو هغۀ جواب راکړو، ”دا هغه څوک دے چې مالِک خُدائ رالېږلے دے چې په دُنيا کښې ګشت وکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21774, 'Zechariah 1:11', 'Zechariah', 1, 11, '&nbsp;او هغوئ د مالِک خُدائ فرښتې ته خبر ورکړو، څوک چې د سر درو ونو په مينځ کښې ولاړه وه، ”مونږ په ټوله دُنيا کښې ګشت وکړو او پته راته ولګېده چې ټوله دُنيا په آرام او امن کښې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21775, 'Zechariah 1:12', 'Zechariah', 1, 12, '&nbsp;بيا د مالِک خُدائ فرښتې وفرمائيل، ”مالِکه خُدايه، ربُ الافواجه، تۀ به ترڅو پورې په يروشلم او د يهوداه په علاقو رحم نۀ کوې، چا ته چې تۀ د اويا کالو نه غصه يې؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21776, 'Zechariah 1:13', 'Zechariah', 1, 13, '&nbsp;نو مالِک خُدائ په رحم او نرم لفظونو هغه فرښتې سره خبرې وکړې چا چې ما سره خبرې کولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21777, 'Zechariah 1:14', 'Zechariah', 1, 14, '&nbsp;بيا هغه فرښتې چا چې ما سره خبرې کولې راته يې وفرمائيل، ”د دې کلام اعلان وکړه چې مالِک خُدائ ربُ الافواج دا فرمائى، زۀ په يروشلم او صيون ډېر زيات غېرت کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21778, 'Zechariah 1:15', 'Zechariah', 1, 15, '&nbsp;خو زۀ هغه نورو قومونو ته ډېر غصه يم چې په امن او سکون کښې ژوند کوى. زۀ خپلو خلقو ته لږ غصه وم، خو دې قومونو هغوئ ته زما د ارادې نه زيات نقصان ورکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21779, 'Zechariah 1:16', 'Zechariah', 1, 16, '&nbsp;په دې وجه، مالِک خُدائ دا فرمائى، زۀ به يروشلم ته واپس رحم سره راشم، او هلته به زما کور بيا آباد شى. او د ناپ تول تارونه به په يروشلم راښکلے شى، دا مالِک خُدائ ربُ الافواج فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21780, 'Zechariah 1:17', 'Zechariah', 1, 17, '&nbsp;نو دا هم ووايه، مالِک خُدائ ربُ الافواج فرمائى چې، زما ښارونه به بيا د برکت نه ډک شى، او مالِک خُدائ به بيا صيون له تسلى ورکړى او يروشلم به لکه د خپل ښار دوباره غوره کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21781, 'Zechariah 1:18', 'Zechariah', 1, 18, '&nbsp;بيا ما بره وکتل، او هلته زما په وړاندې څلور ښکرونه وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21782, 'Zechariah 1:19', 'Zechariah', 1, 19, '&nbsp;ما تپوس وکړو، د هغه فرښتې نه چې ما سره يې خبرې کولې، ”دا څۀ دى؟“ هغې جواب راکړو، ”دا هغه ښکرونه دى چې يهوداه، اِسرائيل او يروشلم يې خوارۀ وارۀ کړى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21783, 'Zechariah 1:20', 'Zechariah', 1, 20, '&nbsp;بيا مالِک خُدائ ما ته څلور لوهاران وښودل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21784, 'Zechariah 1:21', 'Zechariah', 1, 21, '&nbsp;ما ترې نه تپوس وکړو چې، ”دا څلور کسان د څۀ دپاره راروان دى؟“ نو فرښتې جواب راکړو، ”دا څلور ښکرونه هغه قومونه دى چې يهوداه يې عاجز او تس نس کړو. نو اوس دا لوهاران راغلى دى چې دا قومونه ويروى او راښکته يې کړى او د هغوئ کبر ختم کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21785, 'Zechariah 2:1', 'Zechariah', 2, 1, '&nbsp;بيا ما بره وکتل، او هلته زما په وړاندې د ناپ تول فيته په لاس يو سړے ولاړ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21786, 'Zechariah 2:2', 'Zechariah', 2, 2, '&nbsp;نو ما ترې نه تپوس وکړو چې، ”تۀ چرته روان يې؟“ هغۀ راته په جواب کښې وفرمائيل، ”د يروشلم ناپ کولو له، چې دا معلوم کړم چې هغه څومره پلن او څومره اوږد دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21787, 'Zechariah 2:3', 'Zechariah', 2, 3, '&nbsp;نو څۀ وخت چې کومې فرښتې ما سره خبرې کولې هغه مخکښې لاړه نو په دې وخت کښې يوه بله فرښته د هغې سره مِلاوېدو دپاره راغله،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21788, 'Zechariah 2:4', 'Zechariah', 2, 4, '&nbsp;او هغې ته يې وفرمائيل، ”په منډه لاړ شه، هغه ځوان سړى ته ووايه چې يروشلم به د دېوالونو نه بغېر ښار وى ځکه چې دې کښې به انسانان او ځناور په ډېر لوئ تعداد وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21789, 'Zechariah 2:5', 'Zechariah', 2, 5, '&nbsp;او زۀ به په خپله د دې نه ګېرچاپېره د اور دېوال يم، مالِک خُدائ فرمائى، او زۀ به په خپله د دې ښار په مينځ کښې جلال يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21790, 'Zechariah 2:6', 'Zechariah', 2, 6, '&nbsp;”راشئ، راشئ. د شمالى مُلک د جلاوطنۍ نه راوتښتئ،“ مالِک خُدائ فرمائى، ”ځکه ما تاسو په ټوله دُنيا کښې څلور واړو طرفونو ته خوارۀ کړئ،“ مالِک خُدائ فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21791, 'Zechariah 2:7', 'Zechariah', 2, 7, '&nbsp;”اے د صيون خلقو راوتښتئ، څوک چې په بابل کښې جلاوطن شوى يئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21792, 'Zechariah 2:8', 'Zechariah', 2, 8, '&nbsp;نو مالِک خُدائ ربُ الافواج داسې فرمائى، ”زۀ هغه جلالى خُدائ هغه قومونو ته راولېږلم، چا چې تۀ لوټ کړے يې، ځکه چې هر څوک چې تا سره ولګى نو هغه د خپلې سترګې ګاټى سره لګى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21793, 'Zechariah 2:9', 'Zechariah', 2, 9, '&nbsp;په يقين سره به زۀ خپل لاس د هغوئ خلاف راوچت کړم نو د هغوئ غلامان به هغوئ لوټ کړى. بيا به تاسو په دې پوهه شئ چې زۀ مالِک خُدائ ربُ الافواج رالېږلے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21794, 'Zechariah 2:10', 'Zechariah', 2, 10, '&nbsp;چغې ووهه او خوشحالى وکړه، اے صيون لورې. ځکه چې زۀ راروان يم، او زۀ به ستاسو په مينځ کښې اوسېږم،“ مالِک خُدائ فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21795, 'Zechariah 2:11', 'Zechariah', 2, 11, '&nbsp;”په هغه ورځ به ډېر قومونه د مالِک خُدائ سره يوځائ شى او هغوئ به زما خلق شى. زۀ به ستاسو په مينځ کښې اوسېږم او تاسو به په دې پوهه شئ چې مالِک خُدائ ربُ الافواج زۀ تاسو ته رالېږلے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21796, 'Zechariah 2:12', 'Zechariah', 2, 12, '&nbsp;مالِک خُدائ به په مقدسه زمکه کښې يهوداه لکه د خپلې حصې ميراث حاصل کړى او يروشلم به بيا لکه د خپل ښار غوره کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21797, 'Zechariah 2:13', 'Zechariah', 2, 13, '&nbsp;اے ټولو انسانانو د مالِک خُدائ په وړاندې خاموش ودرېږئ، ځکه چې هغه په خپله د خپل مقدس ځائ نه راوچت شوے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21798, 'Zechariah 3:1', 'Zechariah', 3, 1, '&nbsp;بيا هغۀ ما ته يشوَع مشر اِمام وښودلو چې د مالِک خُدائ د فرښتې په وړاندې ولاړ وو، او اِلزام لګوونکے يعنې شېطان د هغۀ په ښى طرف ولاړ وو چې په هغۀ اِلزام ولګوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21799, 'Zechariah 3:2', 'Zechariah', 3, 2, '&nbsp;مالِک خُدائ شېطان ته وفرمائيل، ”مالِک خُدائ تا رټى، شېطانه. هغه مالِک خُدائ، چا چې يروشلم غوره کړے دے، هغه تا رټى. آيا دا سړے هغه سوزېدونکې لرګى په شان نۀ دے چې د اور نه راښکلے شوے وى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21800, 'Zechariah 3:3', 'Zechariah', 3, 3, '&nbsp;اوس يشوَع په ګنده جامو کښې د فرښتې په مخکښې ولاړ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');